require'json';require'find';require'fileutils';root=File.expand_path('..',__dir__);trees=[root,File.expand_path('../Client',root)];skip=%r{/(?:\.git|target|build|work|logs|node_modules|temp|library)(?:/|$)}i;reserved=/\A(?:con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\..*)?\z/i;bad=[];count=0;trees.each{|tree|Find.find(tree){|p|if File.directory?(p)&&p!=tree&&p.match?(skip);Find.prune;next;end;next if p==tree;count+=1;name=File.basename(p);reasons=[];reasons<<'space' if name.include?(' ');reasons<<'control' if name.match?(/[\x00-\x1f\x7f]/);reasons<<'trailing-dot-or-space' if name.match?(/[\. ]\z/);reasons<<'windows-reserved' if name.match?(reserved);reasons<<'platform-punctuation' if name.match?(/[<>:"|?*]/);reasons<<'unicode-format' if name.each_codepoint.any?{|cp|(0x200B..0x200F).cover?(cp)||(0x202A..0x202E).cover?(cp)||(0x2060..0x206F).cover?(cp)||cp==0xFEFF};bad<<{path:p.delete_prefix(tree+'/'),reasons:reasons}unless reasons.empty?}};result={task:'FS02',passed:bad.empty?,scannedPaths:count,violations:bad};out=File.join(root,'docs/generated/fs02-illegal-names.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(result)+"\n");abort("FS02 illegal names: #{bad.take(20)}")unless bad.empty?
